create table if not exists public.content_brand_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id),segment text,audience text,voice_tone text not null default 'professional',preferred_words text[] not null default '{}',forbidden_words text[] not null default '{}',default_cta text,colors jsonb not null default '[]',logo_path text,visual_style text,primary_goal text,networks text[] not null default '{}',notes text,version integer not null default 1,created_by uuid references public.profiles(id),updated_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.content_projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),request_id uuid not null,type text not null check(type in('instagram_post','caption','reels','stories','campaign','ideas','calendar','image','package')),objective text,platform text not null default 'instagram',briefing jsonb not null default '{}',text_content jsonb not null default '{}',status text not null default 'draft' check(status in('draft','generating','ready_for_review','approved','archived','failed','cancelled')),version integer not null default 1,parent_project_id uuid references public.content_projects(id),created_by uuid not null references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,request_id));
create table if not exists public.content_images(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.content_projects(id),request_id uuid not null,briefing_hash text not null,model text not null,size text not null,quality text,status text not null check(status in('generating','ready_for_review','approved','failed','cancelled')),storage_path text,mime_type text,width integer,height integer,usage jsonb not null default '{}',version integer not null default 1,created_by uuid not null references public.profiles(id),approved_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,request_id));
create index if not exists content_projects_org_created_idx on public.content_projects(organization_id,created_at desc) where deleted_at is null;create index if not exists content_projects_org_status_idx on public.content_projects(organization_id,status,type) where deleted_at is null;create index if not exists content_images_org_created_idx on public.content_images(organization_id,created_at desc);
do $$ declare t text;begin foreach t in array array['content_brand_profiles','content_projects','content_images'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select using(public.is_org_member(organization_id))',t||'_select',t);execute format('create policy %I on public.%I for insert with check(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[]))',t||'_insert',t);execute format('create policy %I on public.%I for update using(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[])) with check(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[]))',t||'_update',t);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('content-assets','content-assets',false,10485760,array['image/png','image/jpeg','image/webp'])on conflict(id)do nothing;create policy content_assets_read on storage.objects for select using(bucket_id='content-assets' and public.is_org_member((storage.foldername(name))[1]::uuid));create policy content_assets_write on storage.objects for insert with check(bucket_id='content-assets' and public.has_org_role((storage.foldername(name))[1]::uuid,array['owner','admin','sales']::public.member_role[]));
